<script setup>import {useForm} from '@inertiajs/vue3';const f=useForm({email:'admin@agency.test',password:'password'});const submit=()=>f.post('/login');</script><template><div class="login"><div class="login-card"><div class="logo"><b>A</b><strong>AgencyOS</strong></div><small>AGENCY OPERATIONS CLOUD</small><h1>Welcome back.</h1><p>Manage projects, people, payments and delivery from one workspace.</p><form @submit.prevent="submit"><label>Email<input v-model="f.email" type="email"></label><label>Password<input v-model="f.password" type="password"></label><div v-if="f.errors.email" class="error">{{f.errors.email}}</div><button>Enter workspace →</button></form><div class="demo">Demo password: <b>password</b><br>admin@agency.test · client@agency.test · team@agency.test · intern@agency.test</div></div></div></template>
